from pathlib import Path
import re

path = Path('/home/ubuntu/agentbreaker/client/src/pages/Home.tsx')
text = path.read_text()
text = text.replace('import { useMemo, useState } from "react";', 'import { useEffect, useMemo, useState } from "react";')

agents = r'''function Agents() { const [registerOpen, setRegisterOpen] = useState(false); const [selectedId, setSelectedId] = useState("agent-demo-001"); const agents = trpc.agents.list.useQuery(); const vulns = trpc.vulnerabilities.list.useQuery(); const [, navigate] = useLocation(); const selected = agents.data?.find(agent => agent.id === selectedId) ?? agents.data?.[0]; const posture = selected && (vulns.data ?? []).some(item => item.executionId && item.severity === "CRITICAL") ? "HIGH RISK" : selected && (vulns.data ?? []).length ? "ATTENTION REQUIRED" : "NO FINDINGS"; return <div className="page-content"><SectionHeading eyebrow="TARGET INVENTORY" title="Target Agents" detail="Controlled AI agents available for security assessment." action={<Button className="primary-btn" onClick={() => setRegisterOpen(true)}><PlusIcon />Register agent</Button>} /><div className="agent-inventory-grid">{(agents.data ?? []).map(agent => <button key={agent.id} className={`agent-inventory-card ${selected?.id === agent.id ? "selected" : ""}`} onClick={() => setSelectedId(agent.id)}><div className="inventory-card-top"><div className="agent-avatar"><Bot size={24} /></div><span className="online-badge"><span className="status-pulse" />{agent.status}</span></div><strong>{agent.name}</strong><p>{agent.description}</p><div className="inventory-meta"><span><small>TYPE</small>{agent.agentType}</span><span><small>ROLE</small>{agent.role}</span><span><small>TOOLS</small>{agent.tools.length}</span></div><div className="inventory-footer"><span className={posture === "NO FINDINGS" ? "posture-ok" : "posture-attention"}>{posture}</span><span>{fmtTime(agent.lastTested)}</span></div></button>)}</div>{selected && <Card className="agent-detail-card"><CardContent><div className="agent-hero-top"><div className="agent-avatar"><Bot size={27} /></div><div><div className="card-kicker">SELECTED TARGET / {selected.agentType}</div><div className="agent-name">{selected.name}</div><div className="agent-sub">{selected.description}</div></div><Button className="primary-btn detail-run" onClick={() => navigate("/attack-lab")}><Play size={15} />Run security test</Button></div><div className="agent-meta"><div><span>VERSION</span><strong>{selected.version}</strong></div><div><span>MODEL</span><strong>{selected.model}</strong></div><div><span>ROLE</span><strong>{selected.role}</strong></div><div><span>POSTURE</span><strong className={posture === "NO FINDINGS" ? "posture-ok" : "critical-text"}>{posture}</strong></div></div><div className="agent-detail-columns"><div><div className="card-kicker">SECURITY POLICY</div>{selected.policy.map(rule => <div className="policy-row" key={rule}><CheckCircle2 size={14} /><span>{rule}</span></div>)}</div><div><div className="card-kicker">TOOLS / PERMISSIONS</div><div className="tool-list">{selected.tools.map(tool => <div className="tool-row" key={tool.name}><div className="tool-symbol"><Server size={14} /></div><div className="tool-copy"><strong>{tool.name}()</strong><span>{tool.description}</span></div><div className="tool-policy"><span>{tool.permission}</span><small>{tool.dataClassification}</small></div></div>)}</div></div></div></CardContent></Card>}<AgentRegistrationDialog open={registerOpen} onOpenChange={setRegisterOpen} onRegistered={agent => setSelectedId(agent.id)} /></div>; }
function PlusIcon() { return <Plus size={15} />; }
'''
attack = r'''function AttackLab({ onComplete }: { onComplete: (id: string) => void }) { const agents = trpc.agents.list.useQuery(); const attacks = trpc.attacks.list.useQuery().data ?? []; const [selectedAgentId, setSelectedAgentId] = useState("agent-demo-001"); const [selected, setSelected] = useState("DE-001"); const [running, setRunning] = useState(false); const [phase, setPhase] = useState(""); const selectedAgent = agents.data?.find(agent => agent.id === selectedAgentId) ?? agents.data?.[0]; const attack = attacks.find(item => item.id === selected); useEffect(() => { if (agents.data?.length && !agents.data.some(agent => agent.id === selectedAgentId)) setSelectedAgentId(agents.data[0].id); }, [agents.data, selectedAgentId]); const run = trpc.tests.run.useMutation({ onSuccess: exec => { setRunning(false); setPhase("TEST COMPLETE"); toast.success(`Test complete against ${exec.agentName} — ${exec.analysis.severity} finding recorded`); window.setTimeout(() => onComplete(exec.id), 350); }, onError: err => { setRunning(false); setPhase(""); toast.error(err.message); } }); const copyPayload = async () => { if (!attack) return; await navigator.clipboard?.writeText(attack.payload); toast.success("Controlled payload copied"); }; const start = () => { if (!selectedAgent || !attack) return; setRunning(true); setPhase("INITIALIZING TEST"); window.setTimeout(() => setPhase("DELIVERING PAYLOAD"), 350); window.setTimeout(() => setPhase("OBSERVING AGENT"), 700); window.setTimeout(() => setPhase("ANALYZING BEHAVIOR"), 1100); run.mutate({ agentId: selectedAgent.id, attackId: selected }); }; return <div className="page-content"><SectionHeading eyebrow="CONTROLLED SIMULATION" title="Attack Lab" detail="Run controlled adversarial tests against a registered target agent." action={<div className="lab-safety"><LockKeyhole size={14} /> LOCAL TARGET ONLY</div>} /><div className="lab-grid"><Card className="lab-config"><CardHeader><div><div className="card-kicker">TEST CONFIGURATION</div><CardTitle>Compose a security test</CardTitle></div><span className="step-count">01 / 03</span></CardHeader><CardContent><label className="field-label">TARGET AGENT</label><select className="agent-target-select" value={selectedAgent?.id ?? ""} onChange={event => setSelectedAgentId(event.target.value)}>{(agents.data ?? []).map(agent => <option value={agent.id} key={agent.id}>{agent.name} · {agent.agentType} · {agent.role}</option>)}</select>{selectedAgent && <div className="selected-agent-summary"><div className="mini-agent"><Bot size={16} /></div><div><strong>{selectedAgent.name}</strong><span>{selectedAgent.model} · {selectedAgent.tools.length} configured tools</span></div><CheckCircle2 size={16} className="selected-check" /></div>}<label className="field-label mt-6">ATTACK SCENARIO</label><div className="attack-options">{attacks.map(item => <button key={item.id} className={`attack-option ${selected === item.id ? "selected" : ""}`} onClick={() => setSelected(item.id)}><div className="attack-option-main"><div className="attack-icon"><Radar size={14} /></div><div><strong>{item.name}</strong><span>{item.category} · {item.id}</span></div></div><div className="attack-meta"><span className="technique-tag">{item.technique}</span><SeverityBadge severity={item.baselineSeverity} /></div></button>)}</div>{attack && <div className="payload-preview"><div className="payload-head"><span>PAYLOAD / CONTROLLED SYNTHETIC</span><button className="copy-btn" onClick={copyPayload}><Copy size={12} />COPY</button></div><pre>{attack.payload}</pre><div className="payload-expected"><CheckCircle2 size={14} /> Expected: {attack.expectedBehavior}</div></div>}{running && <div className="execution-progress"><div className="progress-top"><span>{phase}</span><span className="spin-label"><RefreshCw size={12} className="spin" />LIVE</span></div><Progress value={phase === "OBSERVING AGENT" ? 52 : phase === "ANALYZING BEHAVIOR" ? 78 : 28} /><div className="progress-steps"><span className={phase !== "" ? "done" : ""}>Payload</span><span className={phase === "OBSERVING AGENT" || phase === "ANALYZING BEHAVIOR" ? "done" : ""}>Observe</span><span className={phase === "ANALYZING BEHAVIOR" ? "done" : ""}>Analyze</span><span>Risk</span></div></div>}<Button className="run-btn" disabled={!attack || !selectedAgent || running} onClick={start}>{running ? <><RefreshCw size={16} className="spin" />{phase || "Running trace..."}</> : phase === "TEST COMPLETE" ? <><Check size={16} />Test complete</> : <><Play size={16} />Run security test</>}</Button><p className="lab-footnote"><LockKeyhole size={13} /> All actions remain inside the AgentBreaker synthetic environment.</p></CardContent></Card><Card className="lab-info"><CardHeader><div><div className="card-kicker">SELECTED TARGET</div><CardTitle>{selectedAgent?.name ?? "Loading agents"}</CardTitle></div><Bot size={17} className="muted-icon" /></CardHeader><CardContent>{selectedAgent && <div className="target-facts"><div><span>AGENT ID</span><strong>{selectedAgent.id}</strong></div><div><span>ROLE</span><strong>{selectedAgent.role}</strong></div><div><span>MODEL</span><strong>{selectedAgent.model}</strong></div><div><span>TOOLS</span><strong>{selectedAgent.tools.length} configured</strong></div></div>}<div className="coverage-list"><Coverage icon={Terminal} title="Tool behavior" text="Was a restricted tool invoked outside the requested capability?" /><Coverage icon={Database} title="Data access" text="Was sensitive synthetic data accessed or moved through the chain?" /><Coverage icon={KeyRound} title="Permissions" text="Did the assigned role match the permission required by the tool?" /><Coverage icon={GitBranch} title="Attack sequence" text="Did suspicious events correlate into a known multi-step chain?" /><Coverage icon={FileText} title="Evidence" text="Is the result backed by a replayable event timeline?" /></div><div className="risk-method"><div className="card-kicker">PROTOTYPE RISK MODEL</div><strong>Impact × Likelihood × Exposure</strong><span>Each dimension is scored 1–5 and normalized to 0–100. This is AgentBreaker's transparent prototype methodology, not an official industry standard.</span></div></CardContent></Card></div></div>; }
'''

text, count_agents = re.subn(r'function Agents\(\).*?(?=function AttackLab)', agents, text, count=1, flags=re.S)
text, count_lab = re.subn(r'function AttackLab\(.*?(?=function Coverage)', attack, text, count=1, flags=re.S)
if count_agents != 1 or count_lab != 1:
    raise SystemExit(f'replacement counts agents={count_agents}, lab={count_lab}')
path.write_text(text)
